Большое спасибо всем, кто прочитал
первую
часть, в этой части мы продолжим разбираться с webrtc и реализуем действительно полезные возможности SFU.
Введение
В прошлой части мы реализовали сигналинг и базовую маршрутизацию видео трансляций между пользователями. В этой части мы реализуем:
Мониторинг сети
- отслеживание статистики подключений и сохранение ее для аналитики.
Simulcast -
одновременная отправка видео в нескольких качествах, чтобы SFU мог выбирать подходящий поток для каждого зрителя в зависимости от его канала.
Ice restart - алгоритм восстановления соединения.
Но перед тем как перейти к реализации новых фичей нашего приложения, нам нужно убедиться, что по итогу у нас не сломается старый функционал. Поэтому пора написать немного тестов.
Тестирование
Чтобы протестировать приложение, при этом не переоткрывая его по сто раз в браузере, напишем тестовый клиент, который будет симулировать работу нашего фронтенда.
pub struct TestClient {
 pub peer_id: Option<Uuid>,
 pub publisher_pc: Arc<RTCPeerConnection>,
 pub subscriber_pc: Arc<RTCPeerConnection>,
 pub sfu_tx: tokio::sync::mpsc::Sender<SignalMessage>,
 pub sfu_rx: tokio::sync::mpsc::Receiver<SignalMessage>,
 pub connected_peers: Arc<Mutex<HashSet<Uuid>>>,
 pub markers: Markers,
}

pub struct Markers {
 pub ice_connected: bool,
 pub send_offer: bool,
 pub receive_answer: bool,
 pub receive_offer: bool,
}
В тестах мы не хотим общаться между клиентом и сервером посредством вебсокетов, поэтому введем трейт, который послужит абстракцией для коммуникации.
pub trait SyncChannel: Send + 'static {
 type Item: From<SignalMessage>;
 type Error: std::error::Error + Debug;
 fn send(&mut self, message: Self::Item) -> 
 impl Future<Output = Result<(), Self::Error>> + Send;
}
И теперь заменим конкретную реализацию на generic-параметр у нашего пользователя.
pub struct User<S: SyncChannel> {
 pub room: Addr<Room<S>>,
 pub peer_id: Uuid,
 // before pub sync_channel: Websocket
 pub sync_channel: S,
 pub publisher: WeakAddr<Publisher<S>>,
 pub subscriber: WeakAddr<Subscriber<S>>,
}
Отныне в тестах мы можем использовать обычные mpsc каналы для сигналинга.
pub struct TestSyncChannel {
 channel: tokio::sync::mpsc::Sender<SignalMessage> 
}

impl SyncChannel for TestSyncChannel {
 type Item = SignalMessage;
 type Error = tokio::sync::mpsc::error::SendError<SignalMessage>;
 async fn send(&mut self, message: SignalMessage) -> Result<(), Self::Error> {
 self.channel.send(message)
 .await?;
 Ok(())
 }
}
Вернемся к нашему тестовому клиенту, в отличие от браузера мы будем стримить обычный видео-файл формата
.ivf
. Поскольку чтение и декодирование это синхронные операции, а запись данных в трек асинхронная, разделим их на
tokio::task::spawn_blocking
и
tokio::task::spawn
.
tokio::task::spawn_blocking(move || {
 let file = File::open("../output.ivf")?;
 let buf_reader = BufReader::new(file);
 let (mut reader, header) = webrtc::media::IVFReader::new(buf_reader)?;
 let sleep_time = Duration::from_millis(
 ((1000 * header.timebase_numerator) / header.timebase_denominator) as u64,
 );
 loop {
 let frame = match reader.parse_next_frame() {
 Ok((frame, _)) => frame,
 Err(_) => {
 let file = File::open("../output.ivf")?;
 let buf_reader = BufReader::new(file);
 reader = IVFReader::new(buf_reader)?.0;
 continue;
 }
 };
 if tx.blocking_send((frame, sleep_time)).is_err() {
 break ;
 }
 std::thread::sleep(sleep_time);
 }
 Ok(())
});
tokio::task::spawn(async move {
 while let Some((frame, duration)) = rx.recv().await {
 video_track
 .sample_writer()
 .write_sample(&Sample {
 data: frame.freeze(),
 duration,
 ..Default::default()
 })
 .await?;
 }
 Result::<_, Error>::Ok(())
});
Реализуем обработку сигналинга на нашем тестовом клиенте.
match message {
 SignalMessage::Welcome { peer_id } => self.send_track(peer_id).await?,
 SignalMessage::PeerLeft { peer_id } => {
 let mut peers = self.connected_peers.lock().await;
 peers.remove(&peer_id);
 }
 SignalMessage::Rtc { target, message_type } => {
 let pc = match target {
 sfu::user::Target::Publisher => &self.publisher_pc,
 sfu::user::Target::Subscriber => &self.subscriber_pc
 };
 match message_type {
 sfu::user::MessageType::Candidate { candidate } => {
 self.handle_ice_candidate(pc, candidate).await?;
 self.markers.ice_connected = true;
 }
 sfu::user::MessageType::Answer { sdp } => {
 let description = RTCSessionDescription::answer(sdp)?;
 self.publisher_pc.set_remote_description(description).await?;
 self.markers.receive_answer = true;
 }
 sfu::user::MessageType::Offer { sdp } => {
 self.handle_offer(sdp).await?;
 self.markers.receive_offer = true;
 },
 sfu::user::MessageType::IceRestart { sdp } => 
 self.handle_ice_restart(target, pc, sdp).await?
 }
 },
}
Напишем тест для проверки подключения одного пользователя к серверу.
#[tokio::test(flavor = "multi_thread")]
async fn connect_one_user_to_room() -> Result<(), Error> {
 tracing_subscriber::fmt::fmt()
 .with_env_filter("webrtc=ERROR,webrtc_ice=ERROR")
 .init();
 let server: sfu::actor::Addr<Server<_>> = Server::default().start();
 let (tx, rx) = tokio::sync::oneshot::channel();
 let _ = server.send(ServerMessage::CreateRoom { name: "".to_string(), response_channel: tx }).await;
 let (_, room) = rx.await?;
 let (channel, mut client, stream) = spawn_test_client().await?;
 let user = User::new(channel, room.clone()).await?;
 let user_id = user.peer_id;
 let addr = user.start();
 addr.add_stream(tokio_stream::wrappers::ReceiverStream::new(stream));
 let _ = room.send(RoomMessage::Join { peer_id: user_id, addr }).await;
 client.setup().await?;
 for _stage in 0 .. 2 {
 client.handle_message().await?;
 } 
 assert_eq!(client.markers.send_offer, true);
 assert_eq!(client.markers.receive_answer, true);
 Ok(())
}
