А также для проверки подключения нескольких пользователей к серверу и к друг другу.
#[tokio::test]
async fn connect_many_users_to_room() -> Result<(), Error> {
 tracing_subscriber::fmt::fmt()
 .with_env_filter("webrtc=ERROR,webrtc_ice=ERROR")
 .init();
 let server: sfu::actor::Addr<Server<_, FileStorage>> = Server::default().start();
 let (tx, rx) = tokio::sync::oneshot::channel();
 let _ = server.send(ServerMessage::CreateRoom { name: "".to_string(), response_channel: tx }).await;
 let (_, room) = rx.await.unwrap();
 let mut tasks = Vec::with_capacity(24);
 let barrier = Arc::new(tokio::sync::Barrier::new(24));
 for _ in 0 .. 24 {
 let (channel, mut client, stream) = spawn_test_client().await?;
 let user = User::new(channel, room.clone()).await?;
 let peer_id = user.peer_id;
 let user = user.start();
 user.add_stream(tokio_stream::wrappers::ReceiverStream::new(stream));
 let _ = room.send(RoomMessage::Join { peer_id, addr: user }).await;
 let barrier = barrier.clone(); 
 let task = tokio::spawn(async move {
 client.setup().await?;
 for _stage in 0 .. 4 {
 client.handle_message().await?;
 } 
 assert_eq!(client.markers.send_offer, true);
 assert_eq!(client.markers.ice_connected, true);
 assert_eq!(client.markers.receive_answer, true);
 assert_eq!(client.markers.receive_offer, true);
 barrier.wait().await;
 Result::<_, Error>::Ok(())
 });
 tasks.push(task);
 }
 futures_util::future::try_join_all(tasks).await.unwrap();
 Ok(())
}
running 1 test
test connect_to_room::connect_many_users_to_room ... ok
test result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 3 filtered out; finished in 2.50s
Тесты показывают, что наш функционал (пока) работает, начнем добавлять изменения!
Мониторинг сети
Мониторинг понадобится нам как для аналитики того, как работает наше приложение, так и для симулькаста, но о нем позже.
Для начала введем абстракцию для хранения записей о статистике.
pub trait Storage: Send + 'static + Sized {
 type Configuration: StorageConfiguration;
 type Error: std::error::Error + Debug;
 fn connect(configuration: &Self::Configuration) 
 -> impl Future<Output = Result<Self, Self::Error>> + Send;
 fn insert(&mut self, item: StorageItem) 
 -> impl Future<Output = Result<(), Self::Error>> + Send;
}

pub trait StorageConfiguration: Send +'static + Sized {
 type Error: std::error::Error + Debug;
 fn from_env() -> Result<Self, Self::Error>;
}
В реальном приложении я думаю использовал бы что то вроде
Сlickhouse
или же вообще подумал о
Kafka
и самими данными управлял бы в отдельном микросервисе, здесь же используем просто запись в файл.
pub struct FileStorage {
 file: tokio::fs::File
}

pub struct FileConfiguration { path: String }
Актор QualityMonitor
Перейдем к самому актору, который будет отслеживать статистику соединения пользователя.
pub struct QualityMonitor<C: SyncChannel, S: Storage> {
 publisher_connection: Arc<RTCPeerConnection>,
 id: Uuid,
 user: Addr<User<C, S>>,
 storage: S,
 last_stats_time: Instant,
 consecutive_high_signals: usize, 
 current_quality: Option<StreamQuality>, 
 current_stats: CurrentStats,
 thresholds: QualityThresholds,
 update_period: Duration,
}
При запуске актора, запустим стрим, который в интервале будет отправлять сигнал, о том что нужно собрать статистику.
async fn starting(&mut self, ctx: &crate::actor::Ctx<'_, Self>) {
 let stream = IntervalStream::new(interval(self.update_period));
 ctx.addr.add_stream(stream, |_| StreamItem::Next(QualityMonitorMessage::Ping));
}
В начале запросим у соединения статистику и посчитаем нужные метрики.
async fn update_stats(&mut self) {
 let stats = self.publisher_connection.get_stats().await;
 let now = std::time::Instant::now();
 let elapsed_secs = now.duration_since(self.last_stats_time).as_secs_f64();
 self.last_stats_time = now;
 // 1. Собираем метрики из отчетов WebRTC
 let (total_bytes, total_packets, total_nacks) = self.collect_video_metrics(&stats);
 // 2. Рассчитываем битрейт
 self.calculate_bitrate(total_bytes, elapsed_secs);
 // 3. Рассчитываем потери пакетов
 self.calculate_packet_loss(total_packets, total_nacks);
 // 4. Сохраняем состояние для следующего шага
 self.current_stats.last_bytes_received = total_bytes;
 self.current_stats.last_packets_received = total_packets;
 self.current_stats.last_nack_count = total_nacks;
}
Сохраним:
async fn save_stats(&mut self) -> Result<(), Error> {
 let item = crate::StorageItem { 
 connection_id: self.id, 
 stats: &self.current_stats, 
 timestamp: Utc::now(), 
 };
 self.storage.insert(item)
 .await
 .map_err(|e| Error::SystemError { message: e.to_string().into() })?;
 Ok(())
}
После обновление метрик, определим какое качество соединения у пользователя.
fn get_quality(&self) -> Option<StreamQuality> {
 if self.current_stats.last_bytes_received == 0 {
 return None
 }
 if self.current_stats.packet_loss > self.thresholds.low_loss || 
 self.current_stats.bitrate_bps < self.thresholds.low_bitrate {
 return Some(StreamQuality::Low);
 }
 if self.current_stats.packet_loss > self.thresholds.mid_loss || 
 self.current_stats.bitrate_bps < self.thresholds.mid_bitrate {
 return Some(StreamQuality::Mid);
 }
 if self.current_stats.packet_loss < self.thresholds.high_loss && 
 self.current_stats.bitrate_bps > self.thresholds.high_bitrate {
 return Some(StreamQuality::High);
 }
 None
}
После обновления статистики сети и определения оптимального уровня качества, реализуем следующую логику:
Инициализация и защита от дребезга (Debounce)
Первичный запуск
: Если текущее качество еще не задано, система сразу выставляет расчетное значение, отправляет пользователю команду
SwitchQualityLayer
и завершает шаг.
Сравнение состояний
: Если текущее качество уже известно, сравниваем его с новым расчетным значением:
Качество упало (Ordering::Less)
: Мы реагируем мгновенно. Снижение качества происходит без задержек, чтобы пользователь не столкнулся с буферизацией. Счетчик стабильных сигналов при этом обнуляется.
Качество не изменилось (Ordering::Equal)
: Переключение не требуется.
Качество выросло (Ordering::Greater)
: Здесь включается защита от ложных срабатываний. Чтобы не повышать качество на основе краткосрочного скачка сети, нам нужно ввести счетчик
consecutive_high_signals
. Качество вырастет только тогда, когда мы получим подряд больше стабильных сигналов, чем указано в константе REQUIRED_STABLE_SIGNALS. До этого момента счетчик просто инкрементируется.
const REQUIRED_STABLE_SIGNALS: usize = 3;
self.update_stats().await;
self.save_stats().await.ok_or_terminate(ctx);
if let Some(quality) = self.get_quality() {
 let current_quality = match self.current_quality {
 Some(current_quality) => current_quality,
 None => {
 self.current_quality = Some(quality);
 self.user
 .send(UserMessage::SwitchQualityLayer { quality })
 .await
 .ok_or_terminate(ctx);
 return;
 }
 };
 let should_switch = match quality.cmp(&current_quality) {
 std::cmp::Ordering::Equal => {
 false
 },
 std::cmp::Ordering::Greater 
 if self.consecutive_high_signals >= REQUIRED_STABLE_SIGNALS => {
 self.consecutive_high_signals = 0;
 true
 }
 std::cmp::Ordering::Greater => {
 self.consecutive_high_signals += 1;
 false
 },
 std::cmp::Ordering::Less => {
 self.consecutive_high_signals = 0;
 true
 }
 };
 if should_switch {
 self.current_quality = Some(quality);
 self.user.send(UserMessage::SwitchQualityLayer { quality })
 .await
 .ok_or_terminate(ctx);
 }
}
Simulcast
Перейдем непосредственно к работе со слоями, но в начале дадим немного теории.
Simulcast
(одновременная трансляция) — это технология в видеосвязи и стриминге, когда устройство отправляет на сервер несколько копий одного видео, но разного качества и размера (например, слабое, среднее и высокое). Сервер сам выбирает, какой поток отдать каждому зрителю в зависимости от его интернета.
Актор VideoLayerManager
Опишем актор, который будет непосредственно заниматься переключением слоев по сигналу от мониторинга.
pub struct VideoLayerManager {
 pub pc: Arc<RTCPeerConnection>,
 pub peer_id: Uuid,
 pub quality_layers: HashMap<StreamQuality, QualityLayer>,
 pub active_track: Arc<RTCRtpSender>,
 pub track: Arc<TrackLocalStaticRTP>,
 pub packet_forwarder: WeakAddr<VideoPacketForwarder>,
 pub connection_quality: StreamQuality,
 pub active_quality: Option<StreamQuality>,
 pub is_forwarder_running: bool,
}
Актор выполняет три задачи:
Создание нового видео трека и подписка на пришедший слой.
Переключение слоев после сигнала о смене качества.
Чтение обратного RTCP-канала и обработки потерь данных при стриминге.
impl VideoLayerManager {
 pub async fn new(
 pc: Arc<RTCPeerConnection>, 
 peer_id: Uuid, 
 codec: Codec, 
 current_connection_quality: StreamQuality,
 quality: StreamQuality,
 quality_layer: QualityLayer,
 ) -> Result<Self, Error> {
 let mut quality_layers = HashMap::new();
 let track: Arc<TrackLocalStaticRTP> = Arc::new(TrackLocalStaticRTP::new(
 RTCRtpCodecCapability {
 mime_type: codec.to_string(),
 ..Default::default()
 },
 format!("video_{peer_id}"),
 format!("video_{peer_id}")
 ));
 let active_track = pc.add_transceiver_from_track(
 track.clone() as Arc<_>,
 Some(RTCRtpTransceiverInit { direction: RTCRtpTransceiverDirection::Sendonly, send_encodings: vec![] })
 )
 .await?
 .sender()
 .await;
 quality_layers.insert(quality, quality_layer);
 let this = Self { pc, peer_id, track, quality_layers, active_track, active_quality: None, connection_quality: current_connection_quality, packet_forwarder: WeakAddr::default(), is_forwarder_running: false };
 Ok(this) 
 }
}
Поскольку треки могут прийти в каком угодно порядке, запустим первый пришедший.
if let Some((quality, layer)) = self.quality_layers.iter().next() {
 let wake_notification = layer.wake_notification.clone();
 self.spawn_notify_task(addr.clone(), *quality, wake_notification);
 self.active_quality = Some(*quality);
 self.packet_forwarder
 .try_send(VideoPacketForwarderMessage::Start {
 quality: *quality,
 gateway_router: layer.gateway_router.clone()
 })
 .await;
}
При добавлении новых слоев проверяем нет ли того, который совпадает по качеству с соединением.
VideoLayerManagerMessage::AddLayer { quality, layer } => {
 self.quality_layers.insert(quality, layer.clone());
 self.spawn_notify_task(ctx.addr.clone(), quality, layer.wake_notification);
 if quality == self.connection_quality {
 let message = VideoPacketForwarderMessage::LayerSwitched {
 gateway_router: layer.gateway_router.clone()
 };
 self.active_quality = Some(quality);
 self.packet_forwarder
 .try_send(message)
 .await
 .ok_or_terminate(ctx);
 }
}
При необходимости смены слоя перешлем сигнал актору
VideoPacketForwarder
(обновленная версия
PacketForwarder
из прошлой статьи, к нему мы скоро вернемся).
VideoLayerManagerMessage::SwitchQualityLayer { to } => {
 let Some(layer) = self.quality_layers.get(&to) else { tracing::warn!("Missing layer"); return ; };
 self.active_quality = Some(to);
 self.connection_quality = to;
 self.packet_forwarder
 .try_send(VideoPacketForwarderMessage::LayerSwitched {
 gateway_router: layer.gateway_router.clone()
 })
 .await
 .ok_or_terminate(ctx);
},
Обработка обратной связи по RTCP (PLI и NACK)
Что такое RTCP и зачем он нужен?
RTCP (RTP Control Protocol)
— это вспомогательный протокол для RTP (Real-time Transport Protocol). В то время как RTP доставляет сам медиапоток (аудио/видео), RTCP работает в обратном направлении. Он собирает статистику о качестве связи (потери, задержки, джиттер) и передает управляющие команды от получателя к отправителю, позволяя адаптировать стрим под текущие условия сети.
Механизмы борьбы с потерями:
PLI
и
NACK
В реальном времени (WebRTC/стриминг) нельзя использовать обычный TCP с его гарантированной доставкой - это вызовет огромные задержки. Поэтому поверх UDP применяются специализированные механизмы обратной связи:
1.
NACK (Negative Acknowledgment)
- Выборочный повтор пакетов
Что это такое:
Сигнал «я потерял конкретные кусочки пазла».
Как работает:
Получатель замечает дыру в порядковых номерах RTP-пакетов (например, пришли 101, 102, 104 - пакет 103 потерян). Он отправляет обратно NACK-пакет со списком утерянных ID. Отправитель находит их в своем локальном кэше (буфере ретрансляции) и высылает повторно.
Плюс:
Экономит трафик, точечно восстанавливая мелкие потери без прерывания видео.
2. PLI (Picture Loss Indication)
- Запрос нового ключевого кадра
Что это такое:
Сигнал «я полностью потерял нить повествования, спасайте».
Как работает:
Если пакетов потеряно слишком много (или потерян критически важный кусок опорного кадра), декодер на стороне клиента больше не может собирать видео. Картинка рассыпается или застывает. Получатель шлет PLI, требуя от источника немедленно сгенерировать и прислать новый полноценный ключевой кадр (Keyframe / I-Frame).
tokio::spawn(async move {
 loop {
 let mut rtcp_buf = [0u8; 1500];
 let Ok((packets, _)) = active_track.read(&mut rtcp_buf).await else { break; };
 for packet in packets {
 if packet.as_any().downcast_ref::<PictureLossIndication>().is_some() {
 let result = addr.send(VideoSubscriptionMessage::ForcePLI).await;
 if result.is_err() {
 return;
 }
 continue;
 }
 if let Some(nack) = packet.as_any().downcast_ref::<TransportLayerNack>() {
 let mut missing_seqs = Vec::new();
 for pair in &nack.nacks {
 let mut packet_list = pair.packet_list();
 missing_seqs.append(&mut packet_list);
 }
 let message = VideoPacketForwarderMessage::MissedPackets(missing_seqs);
 let result = forwarder.send(message).await;
 if result.is_err() {
 return;
 };
 }
 }
 }
});
Актор KeyframeInterceptor
Опишем актор для отправления сигнала, о том что необходимо сформировать ключевой кадр.
pub struct KeyframeInterceptor {
 pc: Arc<RTCPeerConnection>,
 ssrc: u32,
 last_keyframe_request: Instant,
}
Ssrc - синхронизационный источник медиапотока (Synchronization Source). Это уникальный идентификатор конкретного видеотрека, для которого данный актор перехватывает и генерирует запросы ключевых кадров.
Реализуем безопасную отправку запроса ключевого кадра (PLI) автору трансляции через PeerConnection. Чтобы частые запросы не перегружали сеть тяжелыми I-кадрами, в коде используется временной ограничитель (Rate Limiter), блокирующий повторную отправку чаще раза в две секунды.
async fn send_pli(&mut self) -> Result<(), crate::Error> {
 let since_last_keyframe = self.last_keyframe_request.elapsed();
 if since_last_keyframe < Duration::from_secs(2) { 
 return Ok(());
 }
 self.pc.write_rtcp(&[Box::new(PictureLossIndication {
 media_ssrc: self.ssrc,
 sender_ssrc: 0
 })]).await?;
 self.last_keyframe_request = Instant::now();
 Ok(()) 
}
